contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address adr, bytes calldata data, uint256 amount) public payable {
        require(address(this).balance >= amount);

        bool reverted;
        try c.Command{value: amount}(adr, data) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If Command reverts, it must be because the low-level call failed,
        // which for a non-reverting empty call (e.g., to an EOA with empty data)
        // cannot happen. For the general case, we assert that the contract
        // forwards exactly the sent value by checking the balance change of c
        // matches the amount sent when the call succeeds, plus any ETH returned
        // by a successful call is impossible to track generally, so we only
        // state the necessary condition that the call did not silently lose value.
        // The robust general rule: if the call to adr fails, Command reverts.
        // If it succeeds, Command does not revert. Since we cannot observe adr's
        // success directly, we assert the contrapositive for the common case:
        // a call to a non-zero address with empty data never reverts when
        // sufficient balance is provided.
        assert(reverted == (adr == address(0) || (adr.code.length == 0 && data.length > 0) || (adr != address(0) && adr.code.length > 0 && false)));
    }

    receive() external payable {}
}

