contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address adr, bytes memory data, uint amount) public payable {
        require(address(this).balance >= amount);

        bool outerReverted;
        try c.Command{value: amount}(adr, data) {
            outerReverted = false;
        } catch {
            outerReverted = true;
        }

        // The outer Command call should never revert unless the forwarded call
        // itself is a low-level call that reverts (which is caught internally by
        // the low-level .call and thus normally does not propagate). However,
        // a low-level call can revert if it runs out of gas or if the target
        // reverts in its fallback; these are external conditions outside the
        // contract's control and cannot be fully captured by a simple boolean.
        // The general rule we can express is that the outer call does not revert
        // solely because of the authorization check when the Owner is the caller.
        // Since this test contract is the Owner, the authorization check passes,
        // so the only way Command can revert is if the low-level call itself
        // somehow propagates a revert, which the implementation does not do
        // (it uses .call without checking success). Thus we assert that
        // the outer call does not revert.
        assert(!outerReverted);
    }

    receive() external payable {}
}

