    constructor(C _c) {
        c = _c;
    }

    function run(address adr, uint amount) public payable {
        require(address(this).balance >= amount);

        uint balBefore = address(c).balance;

        bool reverted;
        try c.multiplicate{value: amount}(adr) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = address(c).balance;

        assert(reverted == (amount < balBefore));
    }

    receive() external payable {}
}

contract InvMutTest {
