contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address adr, uint amount) public payable {
        require(adr != address(0), "recipient must be nonzero");
        require(address(this).balance >= amount, "not enough balance to send amount");

        uint cBalBefore = address(c).balance;
        uint adrBalBefore = adr.balance;

        bool reverted;
        try c.multiplicate{value: amount}(adr) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint cBalAfter = address(c).balance;
        uint adrBalAfter = adr.balance;

        // General rule: multiplicate always succeeds (never reverts), and if msg.value >= the
        // contract balance before the call, the recipient receives exactly balanceBefore + amount;
        // otherwise no Ether is transferred.
        assert(
            !reverted &&
            (
                (amount >= cBalBefore && adrBalAfter == adrBalBefore + cBalBefore + amount && cBalAfter == 0) ||
                (amount < cBalBefore && adrBalAfter == adrBalBefore && cBalAfter == cBalBefore + amount)
            )
        );
    }

    receive() external payable {}
}

